/// Clinical working draft combining the supplied specification with the
/// Base44 EKG module's organization. Not covered by Special Considerations signoff.
class EkgEntry {
  const EkgEntry(this.title, this.category, this.sections, this.sources);
  final String title;
  final String category;
  final Map<String, String> sections;
  final List<String> sources;
}

const bradySource = 'https://www.acc.org/-/media/Non-Clinical/Files-PDFs-Excel-MS-Word-etc/Guidelines/2018/Guidelines_Made_Simple_2018_Bradycardia.pdf';
const periopSource = 'https://professional.heart.org/-/media/PHD-Files-2/Science-News/2/2024/2024-Guideline-for-Perioperative-Cardiovascular-Management-slide-set.pdf?sc_lang=en';
const alsSource = 'https://cpr.heart.org/en/resuscitation-science/cpr-and-ecc-guidelines/executive-summary';
const afSource = 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11104284/';
const qtSource = 'https://resources.wfsahq.org/wp-content/uploads/atow-449-00.pdf';
const deviceSource = 'https://www.acc.org/latest-in-cardiology/ten-points-to-remember/2024/07/17/14/48/periprocedural-management-and';
const stSource = 'https://litfl.com/st-segment-ecg-library/';
const ecgSource = 'https://litfl.com/ecg-library/diagnosis/';
const standardMonitoring = 'Continuous ECG, blood pressure, oxygenation and ventilation monitoring appropriate to the anesthetic. Obtain a diagnostic 12-lead ECG for a new or concerning change; a monitor strip does not replace it.';
const stableDecision = 'A stable, previously evaluated finding is not an automatic reason to cancel. New symptoms, hemodynamic compromise or an unexplained new abnormality require evaluation before elective anesthesia. Urgent surgery requires an individualized risk and treatment plan.';

EkgEntry rhythm(String title, String findings, String anesthesia,
    String decision, String monitoring, List<String> sources) =>
  EkgEntry(title, 'Rhythm Library', {
    'Key ECG Findings': findings,
    'Anesthesia Considerations': anesthesia,
    'Proceed vs Delay Considerations': decision,
    'Monitoring Requirements': monitoring,
  }, sources);

final ekgEntries = <EkgEntry>[
  rhythm('Atrial Fibrillation',
    'Irregularly irregular ventricular rhythm without consistent discrete P waves. QRS is often narrow, but aberrancy or pre-excitation can widen it.',
    'Assess ventricular rate, perfusion, triggers, ventricular function and the anticoagulation plan. Treat contributors such as pain, anemia and infection. Pre-excited AF is a distinct high-risk pathway; do not treat it as routine narrow-complex AF.',
    'Evaluate new or uncontrolled AF before elective anesthesia. Hemodynamic instability caused by AF requires urgent cardioversion, not routine elective progression.',
    '$standardMonitoring Review rate trends and reassess postoperative stroke risk and follow-up.',
    [afSource, periopSource, alsSource]),
  rhythm('Atrial Flutter',
    'Organized flutter activity, often sawtooth in inferior leads. Fixed AV conduction may give a regular ventricular rhythm; variable conduction may be irregular.',
    'Assess rate, perfusion, precipitating factors and thromboembolic risk. Do not assume a regular rhythm excludes an atrial arrhythmia.',
    'Evaluate new or poorly controlled flutter before elective anesthesia. Instability attributable to the rhythm calls for urgent electrical cardioversion.',
    standardMonitoring, [afSource, alsSource, periopSource]),
  rhythm('SVT',
    'Often a regular narrow-complex tachycardia with P waves hidden in or near the QRS. SVT is a category, not a single mechanism; flutter and sinus tachycardia remain important alternatives.',
    'Assess the patient before treating the tracing. Correct triggers and determine stability and QRS regularity/width. Do not apply a regular narrow-complex pathway to an irregular wide-complex rhythm.',
    'Resolve active sustained unexplained tachycardia before elective anesthesia. Instability requires immediate rhythm-directed resuscitation.',
    '$standardMonitoring Have cardioversion capability immediately available for significant active tachyarrhythmia.',
    [alsSource, periopSource, ecgSource]),
  rhythm('Junctional Rhythm',
    'Absent, inverted or retrograde P waves, sometimes before, within or after the QRS. QRS is usually narrow unless there is associated conduction disease.',
